import React, { useContext } from "react";
import PasswordContext from "../store/password-context";
const SavedPassword = () => {
  const usePassword = useContext(PasswordContext);

  const deleteHandler = (itemId) => {
    usePassword.removeItem(itemId);
  };

  const editItemHandler = (itemId) => {
   
  };

  return (
    <div>
      {usePassword.openProduct && (
        <ul style={{marginLeft:"0px"}}>
               <h3>All Passwords :</h3>
          {usePassword.item.map((item) => (
            <li key={item.id} style={{ display: "flex" }}>
            
              <p>Title: {item.title} </p>
             
              <p style={{ marginLeft: "10px",marginRight:"10px" }}> Password :{item.password}</p>

              <button
                style={{ cursor: "pointer" ,height:"25px",width:"80px",alignSelf: "center"}}
                onClick={() => deleteHandler(item.id)}
              >
                Delete
              </button>
              <button
                style={{ cursor: "pointer" ,height:"25px",width:"80px",alignSelf: "center"}}
                onClick={() => editItemHandler(item.id)}
              >
                Edit
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};
export default SavedPassword;
